// scramble: glifo determinístico por (índice, passo de tempo); revela da esquerda
const GL = "!<>-_/[]{}=+*^?#ABCDEFGHJKMNPRSTUVWXYZ0123456789", word = el.dataset.text, sc = { p: 0 };
tl.fromTo(sc, { p: 0 }, { p: 1, duration: 0.8, ease: "none", onUpdate: () => {
  const shown = Math.floor(sc.p * word.length), step = Math.floor(tl.time() * 20);
  el.textContent = [...word].map((ch, i) => i < shown || ch === " " ? ch : GL[(i * 31 + step * 17) % GL.length]).join("");
} }, t);

// slam: el = palavra, scene = palco que treme
tl.fromTo(el, { scale: 2.4, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.22, ease: "power4.out" }, t);
tl.fromTo(scene, { y: 0 }, { keyframes: { y: [0, 14, -9, 5, 0] }, duration: 0.3, ease: "none" }, t + 0.2);

// text swap: a = palavra antiga, b = palavra nova, empilhadas dentro de .slot { overflow: hidden }
tl.fromTo(a, { yPercent: 0 }, { yPercent: -100, duration: 0.35, ease: "power3.inOut" }, t);
tl.fromTo(b, { yPercent: 100 }, { yPercent: 0, duration: 0.35, ease: "power3.inOut" }, t);

// typewriter: texto completo em data-text, revela por contagem (seek-safe)
const full = el.dataset.text, p = { n: 0 };
tl.fromTo(p, { n: 0 }, { n: full.length, duration: full.length * 0.035, ease: "none",
  onUpdate: () => { el.textContent = full.slice(0, Math.round(p.n)); } }, t);
// cursor piscando em loop finito
const cursor = scene.querySelector(".cursor"), blinks = Math.ceil((full.length * 0.035 + 1) / 0.5);
for (let k = 0; k < blinks; k++) tl.set(cursor, { opacity: k % 2 ? 0 : 1 }, t + k * 0.5);

// word reveal: items = spans .w; tempos de words.json em data-words
const words = JSON.parse(scene.dataset.words || "[]");
if (words.length) words.forEach((w, i) => tl.fromTo(items[i], { opacity: 0.15 }, { opacity: 1, duration: 0.12 }, w.start - 0.05));
else tl.fromTo(items, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.3, ease: "power3.out", stagger: 0.12 }, t);

// cada letra atravessa a rampa de densidade e assenta; ordem do centro para fora
const RAMP = " .:-=+*#%@", n = items.length, p = { v: 0 };
tl.fromTo(p, { v: 0 }, { v: 1, duration: 1.0, ease: "none", onUpdate: () => {
  items.forEach((ch, i) => {
    const d = Math.abs(i - (n - 1) / 2) / Math.max(n / 2, 1), local = Math.min(Math.max((p.v - d * 0.4) / 0.6, 0), 1);
    ch.textContent = local >= 1 ? ch.dataset.char : RAMP[Math.floor(local * (RAMP.length - 1))];
  });
} }, t);

// todas desfocadas; o foco passa de uma palavra para a próxima
const per = 0.4;
tl.set(items, { filter: "blur(10px)", opacity: 0.5 }, t);
items.forEach((w, i) => {
  tl.to(w, { filter: "blur(0px)", opacity: 1, duration: 0.2, ease: "power2.out" }, t + i * per);
  if (i < items.length - 1) tl.to(w, { filter: "blur(10px)", opacity: 0.5, duration: 0.2, ease: "power2.in" }, t + (i + 1) * per);
});

// letras se soltam em ordem fixa embaralhada, balançam e caem com gravidade
const order = [3, 0, 5, 1, 4, 2, 6, 8, 7];
items.forEach((ch, i) => {
  const d = (order[i % order.length] + Math.floor(i / order.length) * order.length) * 0.07, s = i % 2 ? 1 : -1;
  tl.fromTo(ch, { rotation: 0, y: 0 }, { rotation: 9 * s, duration: 0.12, ease: "power1.out" }, t + d);
  tl.to(ch, { y: 1400, rotation: 50 * s, duration: 0.7, ease: "power2.in" }, t + d + 0.12);
});

// items = blocos de legenda com data-start/data-end (de words.json)
items.forEach((chunk) => {
  const s = Number(chunk.dataset.start), e = Number(chunk.dataset.end);
  tl.fromTo(chunk, { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.15, ease: "power2.out" }, s);
  tl.set(chunk, { opacity: 0 }, e);
});

// items = blocos (.chunk) com data-start/end; cada .w tem data-start/end e uma cópia colorida .hot
items.forEach((chunk) => {
  const c0 = Number(chunk.dataset.start), c1 = Number(chunk.dataset.end);
  tl.fromTo(chunk, { scale: 0.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.15, ease: "back.out(2)" }, c0);
  tl.set(chunk, { opacity: 0 }, c1);
  chunk.querySelectorAll(".w").forEach((w) => {
    const s = Number(w.dataset.start), e = Number(w.dataset.end), hot = w.querySelector(".hot");
    tl.fromTo(w, { scale: 1 }, { keyframes: { scale: [1, 1.15, 1.08] }, duration: 0.18, ease: "power2.out" }, s);
    tl.fromTo(hot, { opacity: 0 }, { opacity: 1, duration: 0.05 }, s);
    tl.set(hot, { opacity: 0 }, e);
    tl.set(w, { scale: 1 }, e);
  });
});

// letras caem e quicam; rotação inicial fixa por índice (determinística)
const ROT = [-14, 9, -6, 12, -10, 7];
tl.fromTo(items, { y: -600, rotation: (i) => ROT[i % ROT.length], opacity: 0 },
  { y: 0, rotation: 0, opacity: 1, duration: 0.8, ease: "bounce.out", stagger: 0.06 }, t);

// a = balão com 3 pontos (items = pontos); b = balão com a mensagem
const beats = 3, cyc = 0.45, tMsg = t + 0.2 + beats * cyc + 0.24;
tl.fromTo(a, { scale: 0.6, opacity: 0, transformOrigin: "0% 100%" }, { scale: 1, opacity: 1, duration: 0.25, ease: "back.out(1.8)" }, t);
tl.fromTo(items, { y: 0 }, { keyframes: { y: [0, -10, 0] }, duration: cyc, ease: "sine.inOut", stagger: 0.12, repeat: beats - 1 }, t + 0.2);
tl.set(a, { opacity: 0 }, tMsg);
tl.fromTo(b, { scale: 0.6, opacity: 0, transformOrigin: "0% 100%" }, { scale: 1, opacity: 1, duration: 0.3, ease: "back.out(1.6)" }, tMsg);

// el = <path> da elipse aberta em volta da palavra
const L = el.getTotalLength();
tl.fromTo(el, { strokeDasharray: L, strokeDashoffset: L, rotation: -4, transformOrigin: "50% 50%" },
  { strokeDashoffset: 0, rotation: 0, duration: 0.7, ease: "power2.inOut" }, t);

// pai com perspective: 800px; letras levantam a partir da base
tl.fromTo(items, { rotationX: -100, opacity: 0, transformOrigin: "50% 100%" },
  { rotationX: 0, opacity: 1, duration: 0.6, ease: "back.out(1.4)", stagger: 0.04 }, t);

// el = texto; a = cópia vermelha; b = cópia ciano (sobrepostas, mix-blend: screen)
const offs = [16, -22, 9, -12, 18, -5, 0];
const SL = ["inset(10% 0% 60% 0%)", "inset(55% 0% 20% 0%)", "inset(30% 0% 45% 0%)", "inset(70% 0% 5% 0%)", "inset(0% 0% 80% 0%)", "inset(40% 0% 35% 0%)", "inset(0% 0% 0% 0%)"];
offs.forEach((o, k) => {
  const tk = t + k * 0.05;
  tl.set(a, { x: o, opacity: o ? 0.8 : 0, clipPath: SL[k] }, tk);
  tl.set(b, { x: -o, opacity: o ? 0.8 : 0, clipPath: SL[(k + 3) % SL.length] }, tk);
  tl.set(el, { x: o * 0.3, skewX: o * 0.4 }, tk);
});

// DrawSVG (grátis no 3.13+): items = traços do lettering na ordem da escrita
let acc = 0;
items.forEach((s) => {
  const L = s.getTotalLength(), d = L / 900; // ~900 px/s de "caneta"
  tl.fromTo(s, { drawSVG: "0%" }, { drawSVG: "100%", duration: d, ease: "power1.inOut" }, t + acc);
  acc += d + 0.04;
});

// el = caixa de acento atrás da frase; items = palavras (posição medida no setup)
const per = 0.35, pos = Array.from(items).map((w) => [w.offsetLeft, w.offsetWidth / 100]);
tl.set(el, { x: pos[0][0], scaleX: pos[0][1], transformOrigin: "0% 50%" }, t);
pos.forEach(([x, k], i) => { if (i) tl.to(el, { x: x, scaleX: k, duration: 0.2, ease: "power3.inOut" }, t + i * per); });

// texto "fervendo": cada letra salta entre offsets fixos a 12 fps durante a cena
const sceneDur = 3, fps = 12, J = [[2, -1, 1], [-2, 1, -1], [1, 2, 0.5], [-1, -2, -0.5]];
for (let k = 0; k < sceneDur * fps; k++) items.forEach((ch, i) => {
  const j = J[(i + k * 3) % J.length];
  tl.set(ch, { x: j[0], y: j[1], rotation: j[2] }, t + k / fps);
});

// items = palavras; cada uma tem cópia colorida .fill por cima; tempos de words.json
const words = JSON.parse(scene.dataset.words || "[]");
items.forEach((w, i) => {
  const fill = w.querySelector(".fill"), ww = words[i] || { start: t + i * 0.3, end: t + i * 0.3 + 0.3 };
  tl.fromTo(fill, { clipPath: "inset(0% 100% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)", duration: ww.end - ww.start, ease: "none" }, ww.start);
});

// a = palavra original; el = cópia na cor de acento, sobreposta (crossfade em vez de tweenar color)
tl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.15, ease: "power2.out" }, t);
tl.fromTo([a, el], { y: 0 }, { y: -6, duration: 0.15, ease: "power2.out" }, t);

// items = linhas (tamanhos variados no CSS); el = coluna que sobe a cada linha nova
const gap = 0.45, lineH = 220;
tl.set(el, { y: 0 }, t);
items.forEach((line, i) => {
  tl.fromTo(line, { scale: 1.6, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "power4.out" }, t + i * gap);
  if (i > 0) tl.to(el, { y: -i * lineH * 0.5, duration: 0.3, ease: "power3.inOut" }, t + i * gap);
});

// el = barra de fundo; a = nome; b = cargo; entra, segura e sai
const hold = 3;
tl.fromTo(el, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.4, ease: "power3.out" }, t);
tl.fromTo(a, { clipPath: "inset(0% 100% 0% 0%)", x: -20 }, { clipPath: "inset(0% 0% 0% 0%)", x: 0, duration: 0.4, ease: "power3.out" }, t + 0.15);
tl.fromTo(b, { yPercent: 100, opacity: 0 }, { yPercent: 0, opacity: 1, duration: 0.35, ease: "power3.out" }, t + 0.3);
tl.to([a, b], { opacity: 0, duration: 0.25, ease: "power2.in" }, t + hold);
tl.to(el, { scaleX: 0, transformOrigin: "100% 50%", duration: 0.35, ease: "power3.in" }, t + hold + 0.1);

// el = <path> em zigue-zague sobre a palavra; a = texto rasurado
const L = el.getTotalLength();
tl.fromTo(el, { strokeDasharray: L, strokeDashoffset: L }, { strokeDashoffset: 0, duration: 0.45, ease: "none" }, t);
tl.fromTo(a, { opacity: 1 }, { opacity: 0.6, duration: 0.3, ease: "power2.out" }, t + 0.1);

// el = faixa com o texto repetido 2x; atravessa uma vez por cena (finito, linear)
const sceneDur = 4;
tl.fromTo(el, { xPercent: 0 }, { xPercent: -50, duration: sceneDur, ease: "none" }, t);

// items = letras com data-char; cada uma cai e troca de glifo até pousar
const GL = "アイウエオカキクケコサシスセソ0123456789", p = { v: 0 }, land = (i) => 0.4 + ((i * 37) % 9) * 0.06;
tl.fromTo(items, { opacity: 0 }, { opacity: 1, duration: 0.01, ease: "none" }, t); // escondidas até a chuva começar
tl.fromTo(items, { y: -700 }, { y: 0, duration: (i) => land(i), ease: "power1.in" }, t);
tl.fromTo(p, { v: 0 }, { v: 1, duration: 1.0, ease: "none", onUpdate: () => {
  const s = tl.time() - t, step = Math.floor(tl.time() * 15);
  items.forEach((ch, i) => { ch.textContent = s >= land(i) ? ch.dataset.char : GL[(i * 13 + step * 7) % GL.length]; });
} }, t);

// a = texto; b = cópia espelhada embaixo (máscara em gradiente no CSS)
tl.fromTo(a, { yPercent: 100, opacity: 0 }, { yPercent: 0, opacity: 1, duration: 0.6, ease: "power3.out" }, t);
tl.fromTo(b, { yPercent: -100, scaleY: -1, opacity: 0 }, { yPercent: 0, scaleY: -1, opacity: 0.35, duration: 0.6, ease: "power3.out" }, t);

// items = palavras empilhadas no mesmo ponto; uma por vez, todas escondidas desde o início
const per = 0.25;
items.forEach((w, i) => {
  tl.fromTo(w, { opacity: 0 }, { opacity: 1, duration: 0.01, ease: "none" }, t + i * per);
  tl.fromTo(w, { scale: 1.25 }, { scale: 1, duration: 0.12, ease: "power3.out" }, t + i * per);
  if (i < items.length - 1) tl.set(w, { opacity: 0 }, t + (i + 1) * per);
});

// items = <path> das letras (texto convertido em curvas), com stroke e fill
items.forEach((p, i) => {
  const L = p.getTotalLength(), ti = t + i * 0.06;
  tl.fromTo(p, { strokeDasharray: L, strokeDashoffset: L, fillOpacity: 0 }, { strokeDashoffset: 0, duration: 0.9, ease: "power2.inOut" }, ti);
  tl.to(p, { fillOpacity: 1, duration: 0.35, ease: "power2.out" }, ti + 0.7);
});

// a = aspas grandes; items = linhas da citação (spans em máscara); b = autor
tl.fromTo(a, { scale: 0.4, opacity: 0, rotation: -12 }, { scale: 1, opacity: 1, rotation: 0, duration: 0.5, ease: "back.out(1.6)" }, t);
tl.fromTo(items, { yPercent: 110 }, { yPercent: 0, duration: 0.7, ease: "power4.out", stagger: 0.12 }, t + 0.3);
tl.fromTo(b, { opacity: 0, x: -40 }, { opacity: 1, x: 0, duration: 0.4, ease: "power3.out" }, t + 0.3 + items.length * 0.12 + 0.4);

// items = letras recortadas (fundos/fontes variados no CSS); tilt fixo por índice
const ROT = [-8, 5, -3, 9, -6, 4, -10, 7];
tl.fromTo(items, { scale: 0, rotation: (i) => ROT[i % ROT.length] * 3 },
  { scale: 1, rotation: (i) => ROT[i % ROT.length], duration: 0.28, ease: "back.out(2.2)", stagger: 0.07 }, t);

// el = palavra-reação estilo adesivo
tl.fromTo(el, { scale: 0, rotation: -25 }, { scale: 1, rotation: -8, duration: 0.3, ease: "back.out(2.6)" }, t);
tl.fromTo(el, { x: 0 }, { keyframes: { x: [0, -8, 7, -4, 0] }, duration: 0.25, ease: "none" }, t + 0.3);
tl.to(el, { scale: 0, rotation: 12, duration: 0.2, ease: "back.in(2)" }, t + 1.2);

// items = colunas .reel com data-index (letra alvo) e data-rows (total de linhas), dentro de máscara
items.forEach((reel, i) => {
  const idx = Number(reel.dataset.index), rows = Number(reel.dataset.rows);
  tl.fromTo(reel, { yPercent: 0 }, { yPercent: -100 * idx / rows, duration: 0.9 + i * 0.08, ease: "power3.out" }, t);
});

// items = palavras empilhadas num tambor 3D (pai com perspective: 800px)
const hold = 0.9, spin = 0.4;
items.forEach((w, i) => {
  const ti = t + i * hold;
  // from com immediateRender: todas começam escondidas no tambor
  tl.fromTo(w, { rotationX: 90, opacity: 0, transformOrigin: "50% 50% -60px" }, { rotationX: 0, opacity: 1, duration: spin, ease: "power3.inOut" }, ti);
  if (i < items.length - 1) tl.fromTo(w, { rotationX: 0, opacity: 1 }, { rotationX: -90, opacity: 0, duration: spin, ease: "power3.inOut", immediateRender: false }, ti + hold);
});

// items = letras com data-char, pai com perspective: 600px
const GL = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", step = 0.06, p = { v: 0 };
const flips = (i) => 6 + ((i * 3) % 5), dur = items.length * 0.04 + 11 * step;
tl.fromTo(p, { v: 0 }, { v: 1, duration: dur, ease: "none", onUpdate: () => {
  const s = tl.time() - t;
  items.forEach((ch, i) => {
    const k = Math.floor((s - i * 0.04) / step);
    ch.textContent = k >= flips(i) - 1 ? ch.dataset.char : GL[(i * 7 + Math.max(k, 0) * 11) % GL.length];
  });
} }, t);
items.forEach((ch, i) => tl.fromTo(ch, { rotationX: -90 }, { rotationX: 0, duration: step, ease: "power1.out", repeat: flips(i) - 1 }, t + i * 0.04));

// a = metade de cima (clip-path inset(0 0 50% 0)); b = metade de baixo (inset(50% 0 0 0))
tl.fromTo(a, { x: -700 }, { x: 0, duration: 0.6, ease: "power4.out" }, t);
tl.fromTo(b, { x: 700 }, { x: 0, duration: 0.6, ease: "power4.out" }, t);

// el = camada de texto iluminado sobre o texto escuro; o recorte circular percorre a frase
tl.fromTo(el, { clipPath: "circle(12% at 0% 50%)" }, { clipPath: "circle(12% at 100% 50%)", duration: 1.6, ease: "sine.inOut" }, t);
tl.to(el, { clipPath: "circle(80% at 100% 50%)", duration: 0.4, ease: "power2.out" }, t + 1.6);

// el = painel sólido com o texto vazado; scene = vídeo de fundo visto pelas letras
tl.fromTo(el, { scale: 8, transformOrigin: "50% 50%" }, { scale: 1, duration: 1.2, ease: "expo.inOut" }, t);
tl.fromTo(scene, { scale: 1.15 }, { scale: 1, duration: 1.6, ease: "power2.out" }, t);

// estica no eixo da entrada e volta como borracha (origem na base)
tl.fromTo(el, { scaleY: 3, scaleX: 0.6, y: -300, opacity: 0, transformOrigin: "50% 100%" },
  { scaleY: 1, scaleX: 1, y: 0, opacity: 1, duration: 0.9, ease: "elastic.out(1, 0.45)" }, t);

// el = linha sobre o texto; a = palavra riscada; b = correção
tl.fromTo(el, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.35, ease: "power3.out" }, t);
tl.fromTo(a, { opacity: 1 }, { opacity: 0.45, duration: 0.25, ease: "power2.out" }, t + 0.25);
tl.fromTo(b, { y: 20, opacity: 0 }, { y: 0, opacity: 1, duration: 0.3, ease: "back.out(1.6)" }, t + 0.4);

// letras penduradas pelo topo; lado alternado por índice
tl.fromTo(items, { rotation: (i) => (i % 2 ? 70 : -70), opacity: 0, transformOrigin: "50% 0%" },
  { rotation: 0, opacity: 1, duration: 1.0, ease: "elastic.out(1, 0.35)", stagger: 0.05 }, t);

// el = palavra; items = 4 cópias atrás dela (outline ou cor mais fraca)
tl.fromTo(el, { scale: 0.9, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.25, ease: "power3.out" }, t);
tl.fromTo(items, { scale: 1, opacity: 0.6 }, { scale: (i) => 1.25 + i * 0.2, opacity: 0, duration: 0.7, ease: "power2.out", stagger: 0.1 }, t + 0.1);

// letras voam para fora a partir do centro; vetores fixos por índice
const n = items.length, YS = [-520, 380, -260, 610, -440, 300], RS = [-140, 95, 200, -80, 160, -210];
tl.fromTo(items, { x: 0, y: 0, rotation: 0, opacity: 1 }, {
  x: (i) => (i - (n - 1) / 2) * 160, y: (i) => YS[i % YS.length], rotation: (i) => RS[i % RS.length],
  opacity: 0, duration: 0.6, ease: "power3.out" }, t);

// letras vêm de posições espalhadas (valores fixos) e se montam
const n = items.length, XO = [120, -90, 60, -140, 80, -50], YS = [480, -560, 330, -410, 620, -290], RS = [120, -160, 90, -200, 140, -110];
tl.fromTo(items, {
  x: (i) => (i - (n - 1) / 2) * -180 + XO[i % XO.length], y: (i) => YS[i % YS.length], rotation: (i) => RS[i % RS.length],
  scale: 2.2, opacity: 0, filter: "blur(12px)" },
  { x: 0, y: 0, rotation: 0, scale: 1, opacity: 1, filter: "blur(0px)", duration: 0.8, ease: "expo.out", stagger: { each: 0.02, from: "edges" } }, t);

// el = faixa de acento; a = título; b = subtítulo
tl.fromTo(el, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.35, ease: "power3.in" }, t);
tl.fromTo(a, { opacity: 0 }, { opacity: 1, duration: 0.01, ease: "none" }, t + 0.35); // escondido desde o início, liga no pico
// a faixa recolhe para a direita com clip-path (trocar transformOrigin no meio da timeline não é seek-safe)
tl.fromTo(el, { clipPath: "inset(0% 0% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 100%)", duration: 0.35, ease: "power3.out", immediateRender: false }, t + 0.35);
tl.fromTo(b, { y: 20, opacity: 0 }, { y: 0, opacity: 1, duration: 0.4, ease: "power3.out" }, t + 0.5);

// abre o espaçamento sem mexer em letter-spacing: cada letra desloca a partir do centro
const n = items.length, k = 14; // px extras por letra
tl.fromTo(items, { x: 0 }, { x: (i) => (i - (n - 1) / 2) * k, duration: 1.2, ease: "power2.out" }, t);

// estados de texto em instantes fixos: digita, erra, apaga, corrige
const STATES = [[0, ""], [0.1, "Edite"], [0.3, "Edite víd"], [0.5, "Edite vídoe"], [0.9, "Edite víd"], [1.05, "Edite vídeo"], [1.25, "Edite vídeos com IA"]], p = { v: 0 };
tl.fromTo(p, { v: 0 }, { v: 1, duration: 1.4, ease: "none", onUpdate: () => {
  const s = tl.time() - t;
  let txt = "";
  for (const [k, v] of STATES) if (s >= k) txt = v;
  el.textContent = txt;
} }, t);

// el = <path> do sublinhado feito à mão, embaixo da palavra
const L = el.getTotalLength();
tl.fromTo(el, { strokeDasharray: L, strokeDashoffset: L }, { strokeDashoffset: 0, duration: 0.5, ease: "power2.out" }, t);

// el = coluna dentro de máscara; items = linhas; sobe um item por vez
const rowH = 140, hold = 0.6, move = 0.3;
tl.set(el, { y: 0 }, t);
tl.set(items, { opacity: 0.3 }, t);
tl.set(items[0], { opacity: 1 }, t);
for (let i = 1; i < items.length; i++) {
  const ti = t + i * (hold + move) - move;
  tl.to(el, { y: -i * rowH, duration: move, ease: "power3.inOut" }, ti);
  tl.to(items[i - 1], { opacity: 0.3, duration: move }, ti);
  tl.to(items[i], { opacity: 1, duration: move }, ti);
}

// loop finito: letras oscilando em fase deslocada durante a cena
// repeat dentro do stagger (por letra); no nível de cima ele repetiria a onda inteira e passaria da cena
const sceneDur = 4, half = 0.6, each = 0.06;
const reps = Math.max(0, Math.floor((sceneDur - each * (items.length - 1)) / half) - 1);
tl.fromTo(items, { y: 12 }, { y: -12, duration: half, ease: "sine.inOut", stagger: { each, repeat: reps, yoyo: true } }, t);

// fonte variável: CSS font-variation-settings: "wght" var(--wght) (CSS var inevitável aqui)
tl.fromTo(el, { "--wght": 200 }, { "--wght": 900, duration: 0.6, ease: "power2.inOut" }, t);
// variação por letra em onda: tl.fromTo(items, { "--wght": 200 }, { "--wght": 900, duration: 0.4, ease: "power2.inOut", stagger: 0.04 }, t);

// el = palavra grande; data-origin = ponto no vão de uma letra (ex.: "38% 52%"); b = próxima cena
const org = el.dataset.origin || "50% 50%";
tl.fromTo(el, { scale: 1, transformOrigin: org }, { scale: 14, duration: 0.8, ease: "power3.in" }, t);
tl.fromTo(b, { scale: 0.7, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.4, ease: "power3.out" }, t + 0.55);
